import "date"
import "regexp"
// Same target matching as the panels: any probe of this base name.
base = regexp.replaceAllString(r: /(_h[123]|_tcp(443)?|_icmp)$/, v: "${target}", t: "")
re = regexp.compile(v: "^(?i)" + regexp.quoteMeta(v: base) + "(_h[123]|_tcp(443)?|_icmp)?$")
// A period is stamped at its start: reach back so one that began before
// the range but ends inside it is still shaded.
from(bucket: "smokeping") |> range(start: date.sub(d: 14d, from: v.timeRangeStart), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "persistent_congestion" and r.target =~ re and (r._field == "end" or r._field == "confidence" or r._field == "jump_ms"))
  |> pivot(rowKey: ["_time", "target"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.end * 1000000000 >= int(v: v.timeRangeStart))
  |> map(fn: (r) => ({_time: r._time, timeEnd: time(v: r.end * 1000000000), text: "Persistent congestion (Jitterbug, experimental) on " + r.target + ": the minimum RTT rose " + (if exists r.jump_ms then string(v: float(v: int(v: r.jump_ms * 10.0)) / 10.0) else "?") + " ms and stayed; confidence " + (if exists r.confidence then string(v: float(v: int(v: r.confidence * 100.0)) / 100.0) else "?"), tags: "experimental"}))

