from(bucket: "smokeping") |> range(start: date.sub(d: 14d, from: v.timeRangeStart), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "loss_degradation" and r.target =~ re and (r._field == "end" or r._field == "mean_loss_pct" or r._field == "class" or r._field == "coverage"))
  |> pivot(rowKey: ["_time", "target"], columnKey: ["_field"], valueColumn: "_value")
