  |> map(fn: (r) => ({_time: r._time, timeEnd: time(v: r.end * 1000000000), text: "Loss degradation (experimental) on " + r.target + ": " + (if exists r.mean_loss_pct then string(v: float(v: int(v: r.mean_loss_pct * 10.0)) / 10.0) else "?") + " % mean loss" + (if exists r.coverage then ", data in " + string(v: int(v: r.coverage * 100.0)) + " % of the span" else ""), tags: "experimental"}))

