from(bucket:"smokeping") |> range(start:v.timeRangeStart, stop:v.timeRangeStop) |> filter(fn:(r)=> r._measurement == "dns_latency" and r.target =~ re and r._field =~ /^ping[0-9]+$/) |> group() |> aggregateWindow(every: v.windowPeriod, fn: (column, tables=<-) => tables |> quantile(q: 0.1, column: column, method: "exact_mean"), createEmpty: false) |> map(fn:(r)=> ({ r with _value: r._value * 1000.0 })) |> set(key:"_field", value:"p10") |> keep(columns:["_time","_value","_field"]) |> group(columns:["_field"])

import "regexp"
// Any name a link brings (Google, Google_h2, cloudflare) selects the whole target:
// drop the probe suffix, then match every probe of that base name, any case.
base = regexp.replaceAllString(r: /(_h[123]|_tcp(443)?|_icmp)$/, v: "${target}", t: "")
re = regexp.compile(v: "^(?i)" + regexp.quoteMeta(v: base) + "(_h[123]|_tcp(443)?|_icmp)?$")
// The window's own percentile: every ping of every cycle in it, pooled. A mean of
// per-cycle percentiles would bias it once a window spans several 5-minute cycles.
from(bucket:"smokeping") |> range(start:v.timeRangeStart, stop:v.timeRangeStop) |> filter(fn:(r)=> r._measurement == "dns_latency" and r.target =~ re and r._field =~ /^ping[0-9]+$/) |> group() |> aggregateWindow(every: v.windowPeriod, fn: (column, tables=<-) => tables |> quantile(q: 0.9, column: column, method: "exact_mean"), createEmpty: false) |> map(fn:(r)=> ({ r with _value: r._value * 1000.0 })) |> set(key:"_field", value:"p90") |> keep(columns:["_time","_value","_field"]) |> group(columns:["_field"])

